package com.blog.controller; import com.blog.dto.CategoryDtos.*; import com.blog.service.BlogServices.CategoryService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/categories") @RequiredArgsConstructor public class CategoryController {private final CategoryService categories;@PostMapping @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<CategoryResponse> create(@Valid @RequestBody CategoryRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(categories.create(r));}@GetMapping public List<CategoryResponse> all(){return categories.findAll();}@GetMapping("/{id}") public CategoryResponse one(@PathVariable Long id){return categories.findById(id);}@PutMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public CategoryResponse update(@PathVariable Long id,@Valid @RequestBody CategoryRequest r){return categories.update(id,r);}@DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){categories.delete(id);}}
